import math
import sys

class Main:
    def main():
        input = sys.stdin.read
        data = input().splitlines()
        n = int(data[0])
        circles = []
        line_idx = 1
        for _ in range(n):
            x, y, r = map(int, data[line_idx].split())
            line_idx += 1
            circles.append(TaskC.Circle(TaskC.Point(x, y), r))
        points_set = set()
        for i in range(n):
            for j in range(i + 1, n):
                inters = TaskC.intersectCircles(circles[i], circles[j])
                if inters is not None:
                    for p in inters:
                        points_set.add(p)
        point_indices = {}
        adjacency = []
        def assign_id(p):
            if p not in point_indices:
                idx = len(point_indices)
                point_indices[p] = idx
                adjacency.append(set())
            return point_indices[p]
        for i in range(n):
            angles = []
            K = 100
            for j in range(K):
                angles.append(2 * math.pi * j / K)
            for p in points_set:
                if circles[i].contains(p):
                    dx = p.x - circles[i].o.x
                    dy = p.y - circles[i].o.y
                    angle = math.atan2(dy, dx)
                    if angle < 0:
                        angle += 2 * math.pi
                    angles.append(angle)
            angles = sorted(set(angles))
            direction = circles[i].o.scale(circles[i].r)
            sorted_angles = sorted(set(angles))
            for a in sorted_angles:
                p = circles[i].o.add(direction.rotate(a))
                assign_id(p)
            for j in range(len(sorted_angles)):
                a1 = sorted_angles[j]
                a2 = sorted_angles[(j + 1) % len(sorted_angles)]
                p1 = circles[i].o.add(direction.rotate(a1))
                p2 = circles[i].o.add(direction.rotate(a2))
                u = point_indices[p1]
                v = point_indices[p2]
                if u != v:
                    adjacency[u].add(v)
                    adjacency[v].add(u)
        total_vertices = len(adjacency)
        total_edges = sum(len(neigh) for neigh in adjacency) // 2
        visited = [False] * total_vertices
        def dfs(node):
            visited[node] = True
            for neighbor in adjacency[node]:
                if not visited[neighbor]:
                    dfs(neighbor)
        component_count = 0
        for i in range(total_vertices):
            if not visited[i]:
                component_count += 1
                dfs(i)
        result = 1 + component_count + total_edges - total_vertices
        print(result)

    class Point:
        def __init__(self, x, y):
            self.x = x
            self.y = y
        def add(self, o):
            return Main.Point(self.x + o.x, self.y + o.y)
        def sub(self, o):
            return Main.Point(self.x - o.x, self.y - o.y)
        def rotate(self, a):
            c = math.cos(a)
            s = math.sin(a)
            return Main.Point(self.x * c - self.y * s, self.x * s + self.y * c)
        def norm(self):
            length = self.length()
            if length < 1e-8:
                return Main.Point(0, 0)
            return self.scale(1.0 / length)
        def scale(self, f):
            return Main.Point(self.x * f, self.y * f)
        def length(self):
            return math.hypot(self.x, self.y)
        def __str__(self):
            return f"{self.x:.6f} {self.y:.6f}"
        def __eq__(self, o):
            if not isinstance(o, Main.Point):
                return False
            return abs(self.x - o.x) < 1e-8 and abs(self.y - o.y) < 1e-8
        def __hash__(self):
            return hash((round(self.x / 1e-8), round(self.y / 1e-8)))
        def __lt__(self, o):
            if abs(self.x - o.x) > 1e-8:
                return self.x < o.x
            return self.y < o.y

    class Circle:
        def __init__(self, o, r):
            self.o = o
            self.r = r
        def contains(self, p):
            return abs(p.sub(self.o).length() - self.r) < 1e-8

    @staticmethod
    def intersectCircles(c1, c2):
        dx = c1.o.x - c2.o.x
        dy = c1.o.y - c2.o.y
        d = math.hypot(dx, dy)
        cosA = (c1.r * c1.r + d * d - c2.r * c2.r) / (2 * c1.r * d) if d != 0 else 1
        if cosA < -1 - 1e-8 or cosA > 1 + 1e-8:
            return None
        if cosA < -1:
            cosA = -1
        if cosA > 1:
            cosA = 1
        alpha = math.acos(cosA)
        dir = c2.o.sub(c1.o).norm()
        res = []
        res.append(c1.o.add(dir.scale(c1.r).rotate(+alpha)))
        res.append(c1.o.add(dir.scale(c1.r).rotate(-alpha)))
        return res

if __name__ == "__main__":
    Main.main()

